'use client';
import { useEffect, useRef, useState } from 'react';
import { useSearchParams } from 'next/navigation';
import Link from 'next/link';
import { ArrowUp, ArrowUpRight, Check, ChevronDown, Copy, Download, Info, MessageSquare, Plus, RotateCcw, Settings2, SlidersHorizontal, Square, Trash2, X, LoaderCircle, Sparkles, Code2, PenLine, Lightbulb, Terminal, PanelRightClose, PanelRightOpen } from 'lucide-react';
import { brand, modelCatalog } from '@/lib/auren/brand';
import { useRuntime } from './platform-shell';
import { Mark, Pill, CopyButton } from './shared';
type Message = {
    id: string;
    role: 'user' | 'assistant';
    content: string;
    sample?: boolean;
};
const prompts = [{ icon: Code2, title: 'Build something useful', text: 'Write a small Python function that batches inference requests.' }, { icon: Lightbulb, title: 'Understand a new idea', text: 'Explain how useful compute connects AI inference and mining.' }, { icon: PenLine, title: 'Find the right words', text: 'Write a short introduction to an open compute network.' }];
const sampleAnswer = `This is a sample response to preview the conversation interface. It was not generated by a live model.\n\nA shared AI compute network connects two kinds of participants:\n\n1. Builders send requests to a model through an API or Playground.\n2. GPU workers run the model and return the inference result.\n3. A verifier checks submitted work before contribution accounting.\n4. A funded reward pool distributes tokens under published rules.\n\nThe intended Perla flow settles rewards on Robinhood while computation runs on worker hardware.\n\nOnce an inference endpoint is configured, turn off Interface preview to send a real request.`;
export function Playground() {
    const { status } = useRuntime();
    const params = useSearchParams();
    const selected = params.get('model');
    const [model, setModel] = useState(modelCatalog.some(m => m.id === selected) ? selected! : modelCatalog[0].id as string);
    const [messages, setMessages] = useState<Message[]>([]);
    const [prompt, setPrompt] = useState('');
    const [sample, setSample] = useState(true);
    const [busy, setBusy] = useState(false);
    const [error, setError] = useState('');
    const [settings, setSettings] = useState(false);
    const [temperature, setTemperature] = useState(.7);
    const [hydrated, setHydrated] = useState(false);
    const end = useRef<HTMLDivElement>(null);
    const controller = useRef<AbortController | null>(null);
    const running = useRef(false);
    useEffect(() => { try {
        if (!selected) {
            const pref = JSON.parse(localStorage.getItem('auren.preferences.v1') || '{}');
            if (modelCatalog.some(m => m.id === pref.model))
                setModel(pref.model);
        }
        const saved = JSON.parse(localStorage.getItem('auren.chat.v1') || '[]');
        if (Array.isArray(saved))
            setMessages(saved.filter(m => m && ['user', 'assistant'].includes(m.role) && typeof m.content === 'string').slice(-30).map(m => ({ ...m, content: m.content.slice(0, 12000) })));
    }
    catch { } setHydrated(true); return () => controller.current?.abort(); }, []);
    useEffect(() => { if (hydrated)
        try {
            localStorage.setItem('auren.chat.v1', JSON.stringify(messages.slice(-30)));
        }
        catch { } }, [messages, hydrated]);
    useEffect(() => end.current?.scrollIntoView({ behavior: 'smooth', block: 'end' }), [messages, busy]);
    const activeModel = modelCatalog.find(m => m.id === model) || modelCatalog[0];
    const update = (id: string, content: string) => setMessages(ms => ms.map(m => m.id === id ? { ...m, content } : m));
    async function send(text = prompt) { if (!text.trim() || running.current)
        return; setError(''); if (!sample && !status.inferenceConfigured) {
        setError('Live inference is not connected yet. Turn on Interface preview to explore the conversation flow.');
        return;
    } if (!sample && model !== status.activeModel) {
        setError('This reference model is not enabled on the configured provider. Choose the active model or use Interface preview.');
        return;
    } const token = sessionStorage.getItem('auren.preprod-token') || ''; if (!sample && !token) {
        setError('Add your pre-production access token in API access before using live inference.');
        return;
    } const c = new AbortController(); controller.current = c; running.current = true; setBusy(true); const user: Message = { id: crypto.randomUUID(), role: 'user', content: text.trim(), sample }; const next = [...messages, user].slice(-28); const answer: Message = { id: crypto.randomUUID(), role: 'assistant', content: '', sample }; setMessages([...next, answer]); setPrompt(''); try {
        if (sample) {
            let i = 0;
            while (i < sampleAnswer.length && !c.signal.aborted) {
                i += 18;
                update(answer.id, sampleAnswer.slice(0, i));
                await new Promise(r => setTimeout(r, 13));
            }
        }
        else {
            const res = await fetch('/api/chat', { method: 'POST', headers: { 'Content-Type': 'application/json', 'Authorization': `Bearer ${token}` }, body: JSON.stringify({ model, temperature, messages: next.filter(m => !m.sample).map(({ role, content }) => ({ role, content })) }), signal: c.signal });
            if (!res.ok) {
                const data = await res.json().catch(() => ({})) as {
                    error?: string;
                };
                throw new Error(data.error || 'The request could not be completed.');
            }
            if (!res.body)
                throw new Error('No response stream received.');
            const reader = res.body.getReader();
            const decoder = new TextDecoder();
            let buffer = '', result = '';
            while (true) {
                const { done, value } = await reader.read();
                buffer += decoder.decode(value, { stream: !done }).replace(/\r\n/g, '\n');
                let index;
                while ((index = buffer.indexOf('\n\n')) >= 0) {
                    const block = buffer.slice(0, index);
                    buffer = buffer.slice(index + 2);
                    for (const line of block.split('\n')) {
                        if (!line.startsWith('data:'))
                            continue;
                        const data = line.slice(5).trim();
                        if (data === '[DONE]')
                            continue;
                        try {
                            const obj = JSON.parse(data);
                            if (obj.error)
                                throw new Error('The provider returned a stream error.');
                            const delta = obj.choices?.[0]?.delta?.content;
                            if (typeof delta === 'string') {
                                result += delta;
                                update(answer.id, result);
                            }
                        }
                        catch (e) {
                            if (e instanceof Error && e.message.includes('provider'))
                                throw e;
                        }
                    }
                }
                if (done)
                    break;
            }
            if (!result)
                throw new Error('The provider returned no text.');
        }
    }
    catch (e) {
        if (!c.signal.aborted) {
            setError(e instanceof Error ? e.message : 'Request failed.');
            setMessages(ms => ms.filter(m => m.id !== answer.id || m.content));
        }
    }
    finally {
        running.current = false;
        setBusy(false);
        controller.current = null;
    } }
    const clear = () => { controller.current?.abort(); setMessages([]); setError(''); setPrompt(''); };
    const exportChat = () => { const blob = new Blob([JSON.stringify({ brand: brand.name, model, messages }, null, 2)], { type: 'application/json' }); const url = URL.createObjectURL(blob); const a = document.createElement('a'); a.href = url; a.download = 'auren-conversation.json'; a.click(); URL.revokeObjectURL(url); };
    return <div className="playground-page"><div className="page-heading"><div><span className="eyebrow">A SPACE FOR YOUR NEXT IDEA</span><h1>Playground<span className="coral">.</span></h1><p>Find a model. Follow a thought. See where it takes you.</p></div><div className="page-heading-actions"><button className="button button-outline button-small" onClick={clear}><Plus size={15}/>New conversation</button><button className="icon-btn" aria-label="Toggle model parameters" aria-expanded={settings} onClick={() => setSettings(!settings)}><SlidersHorizontal size={19}/></button></div></div><div className="playground-layout"><section className="chat-panel"><div className="chat-toolbar"><div className="model-select-wrap"><span className={`model-icon small-model-icon ${activeModel.tone}`}>{activeModel.letter}</span><select aria-label="Select inference model" value={model} onChange={e => setModel(e.target.value)} disabled={busy}>{modelCatalog.map(m => <option key={m.id} value={m.id}>{m.name} · {m.size}</option>)}</select></div><div className="chat-toolbar-right"><Pill tone={sample ? 'coral' : status.inferenceConfigured ? 'green' : 'neutral'}>{sample ? 'Interface preview' : status.inferenceConfigured ? 'Live endpoint' : 'Not connected'}</Pill><button className="icon-btn" aria-label="Export conversation" disabled={!messages.length || busy} onClick={exportChat}><Download size={16}/></button></div></div><div className="chat-messages" aria-live="polite" aria-busy={busy}>{!messages.length ? <div className="chat-welcome"><div className="chat-welcome-mark"><Mark /></div><span className="micro">A LITTLE CURIOSITY GOES A LONG WAY</span><h2>What’s on<br /><em>your mind?</em></h2><p>Your next project, a difficult question,<br />or the beginning of something new.</p><div className="suggestion-grid">{prompts.map(p => <button key={p.title} onClick={() => setPrompt(p.text)}><p.icon size={19}/><strong>{p.title}</strong><span>{p.text}</span><ArrowUpRight size={14}/></button>)}</div></div> : messages.map(m => <article key={m.id} className={`chat-message message-${m.role}`}><span className="message-avatar">{m.role === 'user' ? 'Y' : <Mark />}</span><div><div className="message-title"><strong>{m.role === 'user' ? 'You' : activeModel.name}</strong>{m.sample && m.role === 'assistant' && <Pill tone="coral">Sample response</Pill>}</div><div className="message-content">{m.content || <span className="thinking"><i /><i /><i /></span>}</div>{m.role === 'assistant' && m.content && !busy && <CopyButton value={m.content} label="Copy response"/>}</div></article>)}<div ref={end}/></div><div className="composer-wrap">{error && <div className="chat-error" role="alert"><Info size={15}/><span>{error}</span><button className="icon-btn" aria-label="Dismiss error" onClick={() => setError('')}><X size={14}/></button></div>}<form className="composer" onSubmit={e => { e.preventDefault(); void send(); }}><textarea aria-label="Your message" placeholder="Ask a question. Start a thought…" value={prompt} maxLength={12000} onChange={e => setPrompt(e.target.value)} onKeyDown={e => { if (e.key === 'Enter' && !e.shiftKey) {
        e.preventDefault();
        void send();
    } }} rows={2}/><div className="composer-bottom"><span>{activeModel.name} <span>·</span> {sample ? 'Sample output' : 'Configured endpoint'}</span>{busy ? <button type="button" className="send-button" onClick={() => controller.current?.abort()} aria-label="Stop response"><Square size={15}/></button> : <button type="submit" className="send-button" disabled={!prompt.trim()} aria-label="Send message"><ArrowUp size={19}/></button>}</div></form><p className="composer-note">{sample ? 'Preview responses are scripted examples, not live model output.' : 'AI can make mistakes. Review important information.'}<span>Enter to send · Shift + Enter for a new line</span></p></div></section><aside className={`parameters-panel ${settings ? 'parameters-open' : ''}`}><div className="panel-header"><h3>Configuration</h3><button className="icon-btn mobile-only" aria-label="Close configuration" onClick={() => setSettings(false)}><X size={16}/></button></div><label className="switch-row"><div><strong>Interface preview</strong><span>Explore with a sample response.</span></div><input type="checkbox" checked={sample} disabled={busy} onChange={e => { setSample(e.target.checked); setError(''); }} role="switch"/></label><div className="parameter"><div><label htmlFor="temperature">Temperature</label><span className="mono">{temperature.toFixed(1)}</span></div><input id="temperature" type="range" min="0" max="2" step=".1" value={temperature} onChange={e => setTemperature(+e.target.value)}/><p>Lower for focused answers.<br />Higher for more variation.</p></div><div className="parameter model-info"><span className="micro">SELECTED CONFIGURATION</span><h4>{activeModel.name}</h4><dl><div><dt>Publisher</dt><dd>{activeModel.family}</dd></div><div><dt>Parameters</dt><dd>{activeModel.size}</dd></div><div><dt>Purpose</dt><dd>{activeModel.category}</dd></div><div><dt>Availability</dt><dd>{status.activeModel === model ? 'Configured' : 'Reference only'}</dd></div></dl></div><div className="parameter"><span className="micro">YOUR CONVERSATION</span><p>History is saved in this browser. Export a copy or start a fresh conversation whenever you like.</p><button className="text-button" onClick={clear} disabled={busy || !messages.length}><Trash2 size={14}/>Clear conversation</button></div><Link href="/docs#inference" className="parameter-doc-link"><BookSymbol />Take it into your application<ArrowUpRight size={14}/></Link></aside></div></div>;
}
function BookSymbol() { return <Code2 size={17}/>; }
